// Bundles tools/month-out/*.json (from tools/month.js) into js/month-data.js for the Analysis section.
const fs = require('fs'), path = require('path');
const dir = path.join(__dirname, 'month-out'), out = {};
for (const f of fs.readdirSync(dir).filter(f => f.endsWith('.json'))) { const d = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')); out[d.network] = d; }
fs.writeFileSync(path.join(__dirname, '..', 'js', 'month-data.js'),
  '/* Generated by tools/month-pack.js from tools/month.js: a simulated month of morning peaks, Fixed vs SAARTHI. */\n'
  + `window.SAARTHI_MONTH = ${JSON.stringify(out)};\n`);
console.log('packed', Object.keys(out).join(', '));
